function drawRegiceGlacierGolem(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 1.6;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.03 * breathSin;
  const sX = 1.0 - 0.015 * breathSin;
  const by = -Math.abs(breathSin) * 2.8;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 28 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Chông băng sau lưng
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.moveTo(-14, by - 6); ctx.lineTo(-28, by - 26); ctx.lineTo(-8,  by - 14); ctx.fill();
  ctx.beginPath(); ctx.moveTo(14,  by - 6); ctx.lineTo(28,  by - 26); ctx.lineTo(8,   by - 14); ctx.fill();

  // 3. Chân nón băng
  ctx.fillStyle = '#bae6fd';
  ctx.beginPath(); ctx.moveTo(-14, by + 20); ctx.lineTo(-10, by + 34); ctx.lineTo(-6,  by + 20); ctx.fill();
  ctx.beginPath(); ctx.moveTo(6,   by + 20); ctx.lineTo(10,  by + 34); ctx.lineTo(14,  by + 20); ctx.fill();

  // 4. Thân tảng băng
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath(); ctx.moveTo(-14, by - 14); ctx.lineTo(0, by - 36); ctx.lineTo(14, by - 14); ctx.fill();
  ctx.fillStyle = '#bae6fd';
  ctx.beginPath(); ctx.roundRect(-14, by - 12, 28, 30, 3); ctx.fill();
  // Vát sáng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-14, by - 12); ctx.lineTo(-6, by - 12); ctx.lineTo(-12, by + 16); ctx.fill();

  // 5. Hai tay
  ctx.fillStyle = '#bae6fd';
  ctx.beginPath(); ctx.roundRect(-30, by - 4, 12, 22, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(18,  by - 4, 12, 22, 3); ctx.fill();

  // 6. 7 Điểm mắt vàng
  if (!blink) {
    ctx.fillStyle = '#facc15';
    const eyes = [[0, -2], [0, -8], [0, 4], [-6, -2], [6, -2], [-10, -6], [10, -6]];
    eyes.forEach(pt => {
      ctx.beginPath(); ctx.arc(pt[0], by + pt[1], 2, 0, Math.PI * 2); ctx.fill();
    });
  }

  ctx.restore();
}
